+        for (int i = 0; i < sources.length; i++) {
+            final String queryAlias = queryNames[i] == null ? "" : " [" + queryNames[i] + "]";
+            final String queryIdentifier = "at index [" + i + "]" + queryAlias;
+            final float weight = weights == null ? DEFAULT_WEIGHT : weights[i];
